type Fighter = { stance?: string; jumpAt?: number; shotAt?: number; [key: string]: unknown };
export const STANCE: Readonly<Record<"stand" | "crouch" | "prone", { speed: number; centre: number; eye: number; window: number; spot: number }>>;
export const ADS: Readonly<{ speed: number; spread: number }>;
export function canAim(weapon: { kind?: string } | null | undefined): boolean;
export const JUMP: Readonly<{ duration: number; height: number; cooldown: number; wander: number }>;
export const PRONE_SETTLE: number;
export function stanceOf(e: Fighter): "stand" | "crouch" | "prone";
export function jumpPhase(e: Fighter, time: number): number | null;
export function airborne(e: Fighter, time: number): boolean;
export function jumpLift(e: Fighter, time: number): number;
export function centreOf(e: Fighter, time: number): number;
export function eyeOf(e: Fighter, time: number): number;
export function windowOf(e: Fighter): number;
export function speedOf(e: Fighter): number;
export function spotRange(e: Fighter, time: number): number;
export function verticalHit(shooter: Fighter, target: Fighter, pitch: number, d: number, time: number): boolean;
export function pitchTo(shooter: Fighter, target: Fighter, d: number, time: number): number;
export function applyStanceInput(e: Fighter, input: Record<string, unknown>, time: number, moving: boolean): void;
export function setStance(e: Fighter, stance: string, time: number): void;
export function settling(e: Fighter, time: number): boolean;
export function lowCover(c: unknown): boolean;
export function botStance(a: unknown, bot: Fighter, foe: Fighter | null | undefined, options: Record<string, boolean>): void;
